struct error
{
    ULONG            magic;
    CRITICAL_SECTION cs;
    WS_HEAP         *heap;
    ULONG            prop_count;
    struct prop      prop[ARRAY_SIZE( error_props )];
    ULONG            strs_count;
    ULONG            strs_size; /* Maximum length of the strs array */
    WS_STRING       *strs;
    WS_FAULT        *fault;
    WS_XML_STRING    fault_action;
};
